import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:path/path.dart' as p;

import '../../shared/toolchain.dart';
import 'manifest_v2.dart';

/// `composer runners`: writes the runner of every platform an app declares
/// `runner: scaffold` — a native project generated by `flutter create`,
/// listed in the `composer:managed:runners` region of the app's `.gitignore`
/// and never committed (RULE-83).
///
/// ```text
/// dart tools/composer/composer.dart runners [--app <id>] [--platform <p>[,<p>…]] [--force] [--offline]
/// ```
///
/// 1. A runner folder that is missing (or every selected one, with `--force`,
///    deleted first) is generated in a temporary directory —
///    `flutter create --no-pub --platforms=<missing,…> --org <app.org>
///    --project-name <pubspec name> <tmp>/<pubspec name>` — and only
///    `<tmp>/<name>/<p>/` is copied into `apps/<id>/<p>/`. Nothing outside the
///    platform folder is written: no sample `test/widget_test.dart` for the
///    barrel gate, no `analysis_options.yaml` replacing the root's (RULE-70).
///    Then `flutter pub get` runs in the app (`flutter pub get --offline`
///    with `--offline`): it writes what a runner needs beside Flutter's
///    template — [kPubGetRunnerFiles], the plugin registrants and
///    `linux/flutter/generated_plugins.cmake` (Windows alike) — so the runner
///    builds with `--no-pub` straight away. It runs again on any later run
///    that finds one of those files missing (a pub get that failed, or a
///    runner an older composer wrote), so a broken runner is repaired, never
///    reported up to date.
/// 2. A fixed patch set, applied on every run and idempotent:
///    - **macos**: `com.apple.security.network.client` in both entitlements
///      files, after the sandbox key (every app talks HTTP);
///    - **web**, when the app links `core_database`: `web/sqlite3.wasm` — the
///      binary the *resolved* `sqlite3` package names, checked against the
///      sha256 it ships in `lib/src/hook/asset_hashes.dart` — and
///      `web/drift_worker.js`, compiled from
///      `platform/infra/database/web/drift_worker.dart` in a temporary
///      directory and copied in only when its bytes differ.
///
/// A file whose bytes would not change is never rewritten, so a second run
/// with nothing changed writes nothing and says the app's runners are up to
/// date. `--offline` makes no network call: `flutter pub get --offline`
/// (from the pub cache), and no `sqlite3.wasm` download (a cached copy is
/// still used).
///
/// An anchor that is not found is an error naming the file, so a change in
/// Flutter's templates is loud, never a silent skip. A `committed` runner is
/// never written.

/// Runs a program and returns its result: `Process.run` in production, a
/// fake in tests.
typedef ProcessRunner = Future<ProcessResult> Function(
  String exe,
  List<String> args, {
  String? workingDirectory,
});

/// Downloads [url] and returns its bytes; throws [SocketException],
/// [HandshakeException] or [HttpException] (a status other than 200) when it
/// cannot.
typedef Fetcher = Future<List<int>> Function(Uri url);

/// The package whose apps get the web database assets.
const String kDatabasePackageName = 'core_database';

/// The drift web worker's source, relative to the repository root.
const String kDriftWorkerSource =
    'platform/infra/database/web/drift_worker.dart';

/// Where the sqlite3 package keeps the hashes of the binaries it releases.
const String kSqliteAssetHashes = 'lib/src/hook/asset_hashes.dart';

/// The entitlement every generated macOS runner gets.
const String kNetworkClientKey = 'com.apple.security.network.client';

/// The entitlement the patch is anchored after.
const String kSandboxKey = 'com.apple.security.app-sandbox';

/// The two entitlements files of a macOS runner, relative to the app.
const List<String> kMacosEntitlements = [
  'macos/Runner/DebugProfile.entitlements',
  'macos/Runner/Release.entitlements',
];

/// What `flutter pub get` writes into a runner of each platform beside
/// Flutter's template, relative to the app: the file a `--no-pub` build of
/// that runner includes. Web has none (its registrant lives under
/// `.dart_tool/`). One missing means pub get has not run since the runner
/// was written.
const Map<String, String> kPubGetRunnerFiles = {
  'android':
      'android/app/src/main/java/io/flutter/plugins/'
      'GeneratedPluginRegistrant.java',
  'ios': 'ios/Runner/GeneratedPluginRegistrant.m',
  'linux': 'linux/flutter/generated_plugins.cmake',
  'macos': 'macos/Flutter/GeneratedPluginRegistrant.swift',
  'windows': 'windows/flutter/generated_plugins.cmake',
};

/// One app, as `composer runners` needs it.
class RunnerApp {
  const RunnerApp({
    required this.id,
    required this.dir,
    required this.pubspecName,
    required this.decl,
    required this.linksDatabase,
  });

  final String id;

  /// Absolute app directory.
  final String dir;

  /// The app package's name, which `flutter create --project-name` gets.
  final String pubspecName;

  final AppDeclaration decl;

  /// Whether the app links `core_database` (composed, or reached through a
  /// composed package's `dependencies:`).
  final bool linksDatabase;
}

/// What `runners` was asked for.
class RunnersRequest {
  const RunnersRequest({
    this.app,
    this.platforms,
    this.force = false,
    this.offline = false,
  });

  /// `--app <id>`, or null for every app.
  final String? app;

  /// `--platform <p>[,<p>…]`, or null for every scaffold platform.
  final List<String>? platforms;

  /// `--force`: delete and regenerate the selected runners.
  final bool force;

  /// `--offline`: no network — `flutter pub get --offline`, no
  /// `sqlite3.wasm` download.
  final bool offline;
}

/// What one step of a run did.
enum _Step {
  /// It wrote (or deleted) a file.
  wrote,

  /// Everything it owns was already in place: nothing written.
  unchanged,

  /// Something it owns is still missing, and a warning said so.
  missing,

  /// It failed, and an error said so.
  failed,
}

/// Reads the arguments after `runners`. Throws a [FormatException] saying
/// what is wrong (exit 64).
RunnersRequest parseRunnersArgs(List<String> args) {
  String? app;
  List<String>? platforms;
  var force = false;
  var offline = false;
  String value(int i, String flag) {
    if (i + 1 >= args.length || args[i + 1].startsWith('-')) {
      throw FormatException('`$flag` needs a value.');
    }
    return args[i + 1];
  }

  for (var i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--app':
        app = value(i, '--app');
        i++;
      case '--platform':
        final names = [
          for (final part in value(i, '--platform').split(','))
            if (part.trim().isNotEmpty) part.trim(),
        ];
        for (final name in names) {
          if (!kPlatformNames.contains(name)) {
            throw FormatException(
              '`--platform $name`: expected one of '
              '${kPlatformNames.join(', ')}.',
            );
          }
        }
        platforms = [...?platforms, ...names];
        i++;
      case '--force':
        force = true;
      case '--offline':
        offline = true;
      default:
        throw FormatException('Unknown argument `${args[i]}` for `runners`.');
    }
  }
  return RunnersRequest(
    app: app,
    platforms: platforms,
    force: force,
    offline: offline,
  );
}

/// Where the sqlite3 binaries are cached between runs:
/// `$XDG_CACHE_HOME`, else `~/.cache` (`%LOCALAPPDATA%` on Windows), then
/// `flutter_monorepo/sqlite3/<tag>/`.
String sqliteCacheDir(String tag, Map<String, String> environment) {
  final String base;
  if (Platform.isWindows) {
    base =
        environment['LOCALAPPDATA'] ??
        p.join(environment['USERPROFILE'] ?? '.', 'AppData', 'Local');
  } else {
    final xdg = environment['XDG_CACHE_HOME'];
    base = xdg != null && xdg.isNotEmpty
        ? xdg
        : p.join(environment['HOME'] ?? '.', '.cache');
  }
  return p.join(base, 'flutter_monorepo', 'sqlite3', tag);
}

/// The release tag and the `sqlite3.wasm` sha256 the resolved `sqlite3`
/// package ships, or null when [source] (its `asset_hashes.dart`) holds
/// neither.
({String tag, String sha256})? parseAssetHashes(String source) {
  final tag = RegExp(
    r'''releaseTag\s*=\s*['"]([^'"]+)['"]''',
  ).firstMatch(source)?.group(1);
  final hash = RegExp(
    r'''['"]sqlite3\.wasm['"]\s*:\s*['"]([0-9a-fA-F]{64})['"]''',
  ).firstMatch(source)?.group(1);
  if (tag == null || hash == null) return null;
  return (tag: tag, sha256: hash.toLowerCase());
}

/// Generates and patches the runners of [apps] (every app, or the one
/// [request] names). Returns the exit code: 0 done (a missing download is a
/// warning), 1 a failed step — each named on [err].
Future<int> generateRunners({
  required String root,
  required List<RunnerApp> apps,
  required RunnersRequest request,
  required ProcessRunner run,
  required Fetcher fetch,
  Map<String, String>? environment,
  void Function(String line)? out,
  void Function(String line)? warn,
  void Function(String line)? err,
}) async {
  final env = environment ?? Platform.environment;
  final void Function(String) info = out ?? (line) => stdout.writeln(line);
  final void Function(String) warning =
      warn ?? (line) => stdout.writeln('[WARNING] $line');
  final void Function(String) error =
      err ?? (line) => stderr.writeln('[ERROR] $line');

  final selected = request.app == null
      ? apps
      : apps.where((a) => a.id == request.app).toList();
  if (selected.isEmpty) {
    error(
      'No app matches `--app ${request.app}`. Known: '
      '${apps.map((a) => a.id).join(', ')}.',
    );
    return 1;
  }

  var failed = false;
  for (final app in selected) {
    final rel = p.posix.relative(
      app.dir.replaceAll(r'\', '/'),
      from: root.replaceAll(r'\', '/'),
    );

    // Which platforms this run writes into: the scaffold ones, or the named
    // ones — and a named one must be a scaffold this app declares.
    final List<PlatformDecl> targets;
    if (request.platforms == null) {
      targets = [
        for (final platform in app.decl.platforms)
          if (platform.isScaffold) platform,
      ];
    } else {
      targets = [];
      for (final name in request.platforms!) {
        final platform = app.decl.platform(name);
        if (platform == null) {
          if (request.app != null) {
            error(
              '$rel/app_manifest.yaml: platforms: `$name` is not declared — '
              'add `$name: { runner: scaffold }` under `platforms:` first',
            );
            failed = true;
          }
          continue;
        }
        if (!platform.isScaffold) {
          error('$rel/$name/ is committed — composer never writes into it');
          failed = true;
          continue;
        }
        if (!targets.contains(platform)) targets.add(platform);
      }
    }
    if (targets.isEmpty) continue;

    if (request.force) {
      for (final platform in targets) {
        final folder = Directory(p.join(app.dir, platform.name));
        if (folder.existsSync()) folder.deleteSync(recursive: true);
      }
    }

    final steps = <_Step>[];

    // 1. flutter create, once per app, for every missing runner.
    final missing = [
      for (final platform in targets)
        if (!Directory(p.join(app.dir, platform.name)).existsSync())
          platform.name,
    ];
    if (missing.isNotEmpty) {
      final created = await _create(app, rel, missing, run, info, error);
      if (!created) {
        failed = true;
        continue;
      }
      steps.add(_Step.wrote);
    }

    // 2. pub get, after a new runner and whenever a runner lacks a file it
    //    writes: what a `--no-pub` build includes. The runner's state
    //    decides, not this run's create — a pub get that failed, or ran
    //    `--offline` without the packages, is repaired by the next run.
    final lacking = [
      for (final platform in targets)
        if (kPubGetRunnerFiles[platform.name] case final file?)
          if (!File(p.join(app.dir, file)).existsSync()) file,
    ];
    if (missing.isNotEmpty || lacking.isNotEmpty) {
      steps.add(
        await _pubGet(
          app: app,
          rel: rel,
          lacking: lacking,
          offline: request.offline,
          run: run,
          info: info,
          error: error,
        ),
      );
    }

    // 3. The patch set, every run.
    for (final platform in targets) {
      switch (platform.name) {
        case 'macos':
          steps.add(_patchEntitlements(app, rel, info, error));
        case 'web':
          if (!app.linksDatabase) continue;
          steps.addAll(
            await _webDatabaseAssets(
              root: root,
              app: app,
              rel: rel,
              run: run,
              fetch: fetch,
              env: env,
              offline: request.offline,
              info: info,
              warning: warning,
              error: error,
            ),
          );
      }
    }
    if (steps.contains(_Step.failed)) failed = true;
    if (steps.every((step) => step == _Step.unchanged)) {
      info(
        '  $rel: up to date (${targets.map((t) => t.name).join(', ')}) — '
        'nothing written',
      );
    }
  }
  return failed ? 1 : 0;
}

/// `flutter pub get` in the app (`--offline`: from the pub cache only): it
/// adds what Flutter generates beside a runner's template — [lacking], the
/// [kPubGetRunnerFiles] still missing — without which a `--no-pub` build of
/// the runner fails. A failure, or a pass that leaves one of [lacking]
/// missing, is an error naming what to do ([_Step.failed]); the next run
/// tries again, because the files are still missing.
Future<_Step> _pubGet({
  required RunnerApp app,
  required String rel,
  required List<String> lacking,
  required bool offline,
  required ProcessRunner run,
  required void Function(String) info,
  required void Function(String) error,
}) async {
  final args = [...flutterArgs, 'pub', 'get', if (offline) '--offline'];
  final shown = 'flutter ${args.skip(flutterArgs.length).join(' ')}';
  info(
    '  $rel: $shown (the plugin files of the runner'
    '${lacking.isEmpty ? '' : ': ${lacking.join(', ')}'})',
  );
  final result = await run(flutterExecutable, args, workingDirectory: app.dir);
  if (result.exitCode != 0) {
    error(
      '$rel: `$shown` failed (exit ${result.exitCode}) — the runner has no '
      'plugin registrants until it passes, so a `--no-pub` build of it '
      'fails; run `dart tools/composer/composer.dart runners --app ${app.id}` '
      'again${offline ? ' online (the pub cache lacks a package)' : ''}, or '
      'build without `--no-pub`:\n${result.stdout}${result.stderr}',
    );
    return _Step.failed;
  }
  final still = [
    for (final file in lacking)
      if (!File(p.join(app.dir, file)).existsSync()) file,
  ];
  if (still.isNotEmpty) {
    error(
      '$rel: `$shown` passed but wrote no ${still.join(', ')} — Flutter moved '
      'what it generates for a runner; a `--no-pub` build of it may fail. '
      'Update kPubGetRunnerFiles in tools/composer/src/runners.dart to where '
      'this Flutter writes it',
    );
    return _Step.failed;
  }
  for (final file in lacking) {
    info('    wrote $rel/$file');
  }
  return _Step.wrote;
}

/// `flutter create` in a temporary directory; copies `<p>/` of each of
/// [platforms] into the app. False (after naming the step) when it fails.
Future<bool> _create(
  RunnerApp app,
  String rel,
  List<String> platforms,
  ProcessRunner run,
  void Function(String) info,
  void Function(String) error,
) async {
  final tmp = Directory.systemTemp.createTempSync('composer_runner_');
  try {
    final project = p.join(tmp.path, app.pubspecName);
    final args = [
      ...flutterArgs,
      'create',
      '--no-pub',
      '--platforms=${platforms.join(',')}',
      '--org',
      app.decl.org,
      '--project-name',
      app.pubspecName,
      project,
    ];
    info(
      '  $rel: flutter create --platforms=${platforms.join(',')} '
      '--org ${app.decl.org} (in a temporary directory)',
    );
    final result = await run(flutterExecutable, args);
    if (result.exitCode != 0) {
      error(
        '$rel: `flutter ${args.skip(flutterArgs.length).join(' ')}` failed '
        '(exit ${result.exitCode}):\n${result.stdout}${result.stderr}',
      );
      return false;
    }
    for (final name in platforms) {
      final from = Directory(p.join(project, name));
      if (!from.existsSync()) {
        error(
          '$rel: flutter create wrote no $name/ folder — check that this '
          'Flutter SDK supports $name (`flutter config`)',
        );
        return false;
      }
      _copyTree(from, Directory(p.join(app.dir, name)));
      info('    wrote $rel/$name/');
    }
    return true;
  } finally {
    tmp.deleteSync(recursive: true);
  }
}

/// Copies every file under [from] into [to], creating the folders it needs.
/// Links are not followed; a file keeps its mode (`gradlew` stays
/// executable).
void _copyTree(Directory from, Directory to) {
  for (final entity in from.listSync(recursive: true, followLinks: false)) {
    if (entity is! File) continue;
    final target = File(
      p.join(to.path, p.relative(entity.path, from: from.path)),
    );
    target.parent.createSync(recursive: true);
    entity.copySync(target.path);
  }
}

/// The network-client entitlement in both macOS entitlements files.
_Step _patchEntitlements(
  RunnerApp app,
  String rel,
  void Function(String) info,
  void Function(String) error,
) {
  var ok = true;
  var wrote = false;
  for (final file in kMacosEntitlements) {
    final f = File(p.join(app.dir, file));
    final where = '$rel/$file';
    if (!f.existsSync()) {
      error(
        '$where: missing — the macOS runner has no entitlements file to '
        'add $kNetworkClientKey to; regenerate it with --force',
      );
      ok = false;
      continue;
    }
    final text = f.readAsStringSync();
    if (text.contains('<key>$kNetworkClientKey</key>')) continue;
    final patched = addNetworkClientEntitlement(text);
    if (patched == null) {
      error(
        '$where: no `<key>$kSandboxKey</key>` followed by `<true/>` to add '
        '$kNetworkClientKey after — Flutter\'s macOS template changed; add '
        '`<key>$kNetworkClientKey</key><true/>` by hand, or eject the runner '
        '(`runner: committed`)',
      );
      ok = false;
      continue;
    }
    f.writeAsStringSync(patched);
    wrote = true;
    info('    patched $where ($kNetworkClientKey)');
  }
  if (!ok) return _Step.failed;
  return wrote ? _Step.wrote : _Step.unchanged;
}

/// [plist] with `<key>com.apple.security.network.client</key><true/>` after
/// the sandbox key and its `<true/>`, indented like them; [plist] itself when
/// the key is already there; null when the anchor is missing.
String? addNetworkClientEntitlement(String plist) {
  if (plist.contains('<key>$kNetworkClientKey</key>')) return plist;
  final lines = plist.split('\n');
  for (var i = 0; i + 1 < lines.length; i++) {
    if (!lines[i].contains('<key>$kSandboxKey</key>')) continue;
    if (lines[i + 1].trim() != '<true/>') return null;
    final indent = RegExp(r'^\s*').firstMatch(lines[i])!.group(0)!;
    lines.insertAll(i + 2, [
      '$indent<key>$kNetworkClientKey</key>',
      '$indent<true/>',
    ]);
    return lines.join('\n');
  }
  return null;
}

/// `web/sqlite3.wasm` and `web/drift_worker.js` for an app that links
/// `core_database`: what each of the two steps did. A failure is named on
/// [error]; a download that cannot be made is a warning ([_Step.missing]).
Future<List<_Step>> _webDatabaseAssets({
  required String root,
  required RunnerApp app,
  required String rel,
  required ProcessRunner run,
  required Fetcher fetch,
  required Map<String, String> env,
  required bool offline,
  required void Function(String) info,
  required void Function(String) warning,
  required void Function(String) error,
}) async {
  final web = p.join(app.dir, 'web');
  final wasm = await _sqliteWasm(
    root: root,
    app: app,
    rel: rel,
    web: web,
    fetch: fetch,
    env: env,
    offline: offline,
    info: info,
    warning: warning,
    error: error,
  );
  final worker = await _driftWorker(root, rel, web, run, info, error);
  return [wasm, worker];
}

Future<_Step> _sqliteWasm({
  required String root,
  required RunnerApp app,
  required String rel,
  required String web,
  required Fetcher fetch,
  required Map<String, String> env,
  required bool offline,
  required void Function(String) info,
  required void Function(String) warning,
  required void Function(String) error,
}) async {
  final sqlite = resolvedPackageRoot(root, 'sqlite3');
  if (sqlite == null) {
    error(
      '$rel/web: no resolved `sqlite3` package in .dart_tool/package_config.json '
      '— run flutter pub get first',
    );
    return _Step.failed;
  }
  final hashesFile = File(p.join(sqlite, kSqliteAssetHashes));
  final hashes = hashesFile.existsSync()
      ? parseAssetHashes(hashesFile.readAsStringSync())
      : null;
  if (hashes == null) {
    // Nothing to check a download against: the hand-placed binary the error
    // asks for is what the app gets, named as unverified on every run — a
    // run that kept failing after it was placed would block configure.
    final placed = File(p.join(web, 'sqlite3.wasm'));
    if (placed.existsSync()) {
      warning(
        '$rel/web/sqlite3.wasm: not verified — sqlite3 '
        '${_packageVersion(sqlite)} ships no asset hash table at '
        '$kSqliteAssetHashes, so the file in place is used as it is; make '
        'sure it is the release of that version',
      );
      return _Step.unchanged;
    }
    error(
      'sqlite3 ${_packageVersion(sqlite)} ships no asset hash table at '
      '$kSqliteAssetHashes — place a matching sqlite3.wasm in $rel/web/ by '
      'hand (docs/en/guides/07_database.md)',
    );
    return _Step.failed;
  }

  final cache = File(p.join(sqliteCacheDir(hashes.tag, env), 'sqlite3.wasm'));
  final target = File(p.join(web, 'sqlite3.wasm'));
  if (!cache.existsSync()) {
    if (target.existsSync() && _sha256Of(target) == hashes.sha256) {
      // In place and verified: nothing to download, even with no cache.
      return _Step.unchanged;
    }
    if (offline) {
      _offline(app, rel, '--offline, and no cached copy', warning);
      return _Step.missing;
    }
    final url = Uri.parse(
      'https://github.com/simolus3/sqlite3.dart/releases/download/'
      '${hashes.tag}/sqlite3.wasm',
    );
    final List<int> bytes;
    try {
      info('    downloading $url');
      bytes = await fetch(url);
    } on SocketException catch (e) {
      _offline(app, rel, e, warning);
      return _Step.missing;
    } on HandshakeException catch (e) {
      _offline(app, rel, e, warning);
      return _Step.missing;
    } on HttpException catch (e) {
      _offline(app, rel, e, warning);
      return _Step.missing;
    }
    final got = sha256.convert(bytes).toString();
    if (got != hashes.sha256) {
      error(
        '$rel/web/sqlite3.wasm: the download from $url has sha256 $got, but '
        'sqlite3 ${hashes.tag} names ${hashes.sha256} — refused, nothing '
        'written',
      );
      return _Step.failed;
    }
    cache.parent.createSync(recursive: true);
    cache.writeAsBytesSync(bytes);
  }

  // Held to the hash on every copy: a cache someone edited, or one a broken
  // download left behind, never reaches an app.
  final cached = cache.readAsBytesSync();
  final cachedSha = sha256.convert(cached).toString();
  if (cachedSha != hashes.sha256) {
    cache.deleteSync();
    error(
      '${cache.path}: sha256 $cachedSha, but sqlite3 ${hashes.tag} names '
      '${hashes.sha256} — deleted; run again to download it afresh',
    );
    return _Step.failed;
  }
  if (target.existsSync() && _sha256Of(target) == hashes.sha256) {
    return _Step.unchanged;
  }
  target.parent.createSync(recursive: true);
  target.writeAsBytesSync(cached);
  info('    wrote $rel/web/sqlite3.wasm (${hashes.tag})');
  return _Step.wrote;
}

String _sha256Of(File file) =>
    sha256.convert(file.readAsBytesSync()).toString();

void _offline(
  RunnerApp app,
  String rel,
  Object why,
  void Function(String) warning,
) => warning(
  '$rel/web: web database assets missing ($why) — run '
  '`dart tools/composer/composer.dart runners --app ${app.id} --platform web` '
  'online',
);

/// `web/drift_worker.js`, compiled from [kDriftWorkerSource] (from the
/// repository root, so its packages resolve) into a temporary directory and
/// copied in only when its bytes differ from the file in place. The `.deps`
/// and `.map` files the compiler writes beside it never reach the app.
Future<_Step> _driftWorker(
  String root,
  String rel,
  String web,
  ProcessRunner run,
  void Function(String) info,
  void Function(String) error,
) async {
  if (!File(p.join(root, kDriftWorkerSource)).existsSync()) {
    error(
      '$rel/web/drift_worker.js: its source $kDriftWorkerSource is missing — '
      'core_database ships it; restore it from git',
    );
    return _Step.failed;
  }
  final tmp = Directory.systemTemp.createTempSync('composer_worker_');
  try {
    final compiled = File(p.join(tmp.path, 'drift_worker.js'));
    final args = [
      ...dartArgs,
      'compile',
      'js',
      '-O4',
      '-o',
      compiled.path,
      kDriftWorkerSource,
    ];
    final result = await run(dartExecutable, args, workingDirectory: root);
    if (result.exitCode != 0 || !compiled.existsSync()) {
      error(
        '$rel/web/drift_worker.js: `dart ${args.skip(dartArgs.length).join(' ')}` '
        'failed (exit ${result.exitCode}):\n${result.stdout}${result.stderr}',
      );
      return _Step.failed;
    }

    var wrote = false;
    // What a run before this one compiled straight into web/.
    for (final extra in ['drift_worker.js.deps', 'drift_worker.js.map']) {
      final f = File(p.join(web, extra));
      if (f.existsSync()) {
        f.deleteSync();
        wrote = true;
      }
    }
    final bytes = compiled.readAsBytesSync();
    final target = File(p.join(web, 'drift_worker.js'));
    if (!target.existsSync() || !_sameBytes(target.readAsBytesSync(), bytes)) {
      target.parent.createSync(recursive: true);
      target.writeAsBytesSync(bytes);
      info('    wrote $rel/web/drift_worker.js');
      wrote = true;
    }
    return wrote ? _Step.wrote : _Step.unchanged;
  } finally {
    tmp.deleteSync(recursive: true);
  }
}

bool _sameBytes(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

/// The root directory of [package] as `<root>/.dart_tool/package_config.json`
/// resolves it, or null when it is not resolved there.
String? resolvedPackageRoot(String root, String package) {
  final file = File(p.join(root, '.dart_tool', 'package_config.json'));
  if (!file.existsSync()) return null;
  final Object? doc;
  try {
    doc = jsonDecode(file.readAsStringSync());
  } on FormatException {
    return null;
  }
  if (doc is! Map || doc['packages'] is! List) return null;
  for (final entry in doc['packages'] as List) {
    if (entry is! Map || entry['name'] != package) continue;
    final uri = entry['rootUri'];
    if (uri is! String) return null;
    // A relative rootUri is relative to the .dart_tool/ folder.
    final resolved = Uri.directory(
      p.join(root, '.dart_tool'),
    ).resolve(uri.endsWith('/') ? uri : '$uri/');
    return p.normalize(resolved.toFilePath());
  }
  return null;
}

/// The `version:` of the package at [dir], else its folder name.
String _packageVersion(String dir) {
  final pubspec = File(p.join(dir, 'pubspec.yaml'));
  if (pubspec.existsSync()) {
    final version = RegExp(
      r'^version:\s*(\S+)',
      multiLine: true,
    ).firstMatch(pubspec.readAsStringSync())?.group(1);
    if (version != null) return version;
  }
  return p.basename(dir);
}

/// The production [ProcessRunner].
Future<ProcessResult> runProcess(
  String exe,
  List<String> args, {
  String? workingDirectory,
}) => Process.run(
  exe,
  args,
  workingDirectory: workingDirectory,
  runInShell: Platform.isWindows,
);

/// The production [Fetcher]: through the proxy the environment names.
Future<List<int>> fetchUrl(Uri url) async {
  final client = HttpClient()..findProxy = HttpClient.findProxyFromEnvironment;
  try {
    final request = await client.getUrl(url);
    final response = await request.close();
    if (response.statusCode != 200) {
      await response.drain<void>();
      throw HttpException('HTTP ${response.statusCode}', uri: url);
    }
    final bytes = <int>[];
    await for (final chunk in response) {
      bytes.addAll(chunk);
    }
    return bytes;
  } finally {
    client.close(force: true);
  }
}
